import{_ as s,C as i,o as r,c as o,a6 as t,E as n}from"./chunks/framework.CA8SQds3.js";const h="/screenshots/execution-coverage.png",c="/screenshots/coverage-file.png",v=JSON.parse(`{"title":"Code reach","description":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage on a scheduled run, by file or by function, and used by test selection, change coverage and preflight.","frontmatter":{"title":"Code reach","description":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage on a scheduled run, by file or by function, and used by test selection, change coverage and preflight.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/code-reach.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/code-reach.html"}],["meta",{"property":"og:title","content":"Code reach | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Which tests execute each application source file, recorded from Chromium's JavaScript coverage on a scheduled run, by file or by function, and used by test selection, change coverage and preflight."}]]},"headers":[],"relativePath":"features/code-reach.md","filePath":"features/code-reach.md","lastUpdated":1792746320000}`),d={name:"features/code-reach.md"};function l(p,e,u,g,f,m){const a=i("DemoExamples");return r(),o("div",null,[e[0]||(e[0]=t(`<h1 id="code-reach" tabindex="-1">Code reach <a class="header-anchor" href="#code-reach" aria-label="Permalink to &quot;Code reach&quot;">​</a></h1><p>Code reach answers &quot;which tests reach this file?&quot; for application code: an opt-in capture records the source files whose functions ran during each test in the browser, so a change to a component or a module maps to the tests that execute it. An ASP.NET Core backend built for coverage adds the code each test ran on the server: <a href="./server-coverage.html">server coverage</a>.</p><h2 id="turn-it-on" tabindex="-1">Turn it on <a class="header-anchor" href="#turn-it-on" aria-label="Permalink to &quot;Turn it on&quot;">​</a></h2><p>Set <code>captureCodeReach: true</code> in the reporter options, or <code>PIWI_CAPTURE_CODE_REACH=true</code>, with the <a href="/guide/capture-fixtures.html">capture fixtures</a> in place. Coverage adds time to every test and reach changes slowly, so turn it on in one scheduled job; a run without it keeps the reach the last one recorded.</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// playwright.config.ts, in the nightly job</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { captureCodeReach: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">process.env.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NIGHTLY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }]],</span></span></code></pre></div><h2 id="what-it-records" tabindex="-1">What it records <a class="header-anchor" href="#what-it-records" aria-label="Permalink to &quot;What it records&quot;">​</a></h2><p>The fixtures start Chromium&#39;s JavaScript coverage on each page the test opens, and on up to 16 pages already open as it starts (a <code>beforeAll</code>&#39;s, an earlier test&#39;s), and at teardown turn each script into source files:</p><ul><li>a module a dev server serves by path (Vite&#39;s <code>/src/components/Pay.vue</code>, <code>/@fs/…</code>) is the file itself;</li><li>a bundle is read through its source map, inline or fetched once per worker (20 MB and 5 seconds at most).</li></ul><p>A file counts when one of its functions ran. A module&#39;s top-level code runs as soon as it is imported, so it does not count, or every eagerly loaded file would be reached by every test. Paths are relative to the repository root; files under <code>node_modules</code> or outside the repository are dropped, and at most 2,000 files are kept per test. Only the paths leave the machine, never code, counts or line numbers.</p><p><code>coverage.browser: &#39;files&#39;</code> is the same as <code>captureCodeReach: true</code>; <code>&#39;functions&#39;</code> adds each function&#39;s start and end line, through the source map, and the file&#39;s git blob: line numbers then leave the machine. With <code>&#39;functions&#39;</code>, the run also records every function the pages&#39; scripts declare, run or not, so the run&#39;s coverage can say how many of a file&#39;s functions ran. A function declared inside a function that never ran is not listed: V8 has not seen it.</p><p>Paths resolve against the Playwright config&#39;s directory, then the repository root. Set <code>codeReachRoots</code> to the dev server&#39;s root when it is elsewhere; for Nuxt that is <code>app/</code>:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">reporter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [[</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;@piwitests/reporter&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, { captureCodeReach: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, codeReachRoots: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] }]],</span></span></code></pre></div><p>When the tests reach several dev servers that serve modules at the same paths (one per portal, each with its own <code>/js/index.ts</code>), give <code>codeReachRoots</code> an object: each origin with its directories, <code>*</code> for every other origin. A script resolves against its own origin&#39;s directories, else those of the page that loaded it, so the key can be the address the tests open:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">codeReachRoots</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;http://localhost:5001&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;portals/admin/src&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;http://localhost:5002&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;portals/customer/src&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  &#39;*&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;shared&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span></code></pre></div><p>Code a bundler or dev server adds (module wrappers, hot-reload hooks) counts for no file.</p><p>With an instrumented backend (the <a href="/guide/backend-logs.html">Nitro or ASP.NET Core packages</a>), the handler file of each route a test called counts as reached too.</p><h2 id="supported-builds" tabindex="-1">Supported builds <a class="header-anchor" href="#supported-builds" aria-label="Permalink to &quot;Supported builds&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Build</th><th>Source maps</th></tr></thead><tbody><tr><td>Vite dev server, Nuxt dev included</td><td>none needed: modules are served by path</td></tr><tr><td>Vite build</td><td><code>build: { sourcemap: true }</code></td></tr><tr><td>Next.js dev, Turbopack or webpack</td><td>on by default</td></tr><tr><td>Next.js build, Turbopack or webpack</td><td><code>productionBrowserSourceMaps: true</code></td></tr><tr><td>webpack build</td><td><code>devtool: &#39;source-map&#39;</code></td></tr></tbody></table><p>The map must be linked from the bundle: <code>sourcemap: &#39;hidden&#39;</code> and webpack&#39;s <code>hidden-source-map</code> write the map but not the comment that names it, so they record nothing.</p><p>Each was checked on a React app (Vite 8, webpack 5.111, Next.js 16.3) and Piwi&#39;s own Nuxt dev suite: every test recorded exactly the files it ran.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>Code reach reads V8&#39;s function coverage, which records only whether each function ran. A test pays for a CDP session on each page it has, a debugger stop and a coverage read for each document it leaves, and a script&#39;s source is read once per worker, so the cost grows with the modules each document loads. One script-heavy page costs about 8% more per test; on a large ASP.NET Core and Vue application, served by Vite dev servers and moving between screens by full page loads, its UI tests took 40 to 50% longer, by file or by function alike: turn it on in a scheduled run there. <a href="/reference/coverage-cost.html">Coverage cost</a> has every mode and how each was measured.</p><h2 id="on-the-execution-page" tabindex="-1">On the execution page <a class="header-anchor" href="#on-the-execution-page" aria-label="Permalink to &quot;On the execution page&quot;">​</a></h2><p>An execution&#39;s <strong>Source</strong> tab lists what the test ran: server files by executed lines, then browser files. A file the failure&#39;s <a href="/guide/concepts.html#suspect-lines">suspect lines</a> name, or that changed since the last pass, is marked. A file with line numbers unfolds to its source at the version the test ran, marking what it ran and, from the run&#39;s own coverage, the executable lines it did not.</p><figure><img src="`+h+'" alt="The Coverage section of an execution&#39;s Source tab"><figcaption>What a failing test ran.</figcaption></figure><h2 id="which-tests-run-a-file" tabindex="-1">Which tests run a file <a class="header-anchor" href="#which-tests-run-a-file" aria-label="Permalink to &quot;Which tests run a file&quot;">​</a></h2><p>A file&#39;s <strong>tests</strong> link, on an execution, a cluster&#39;s suspect lines or the <a href="./scenario-gaps.html">Test Map</a>, opens its coverage page: its source at the version most tests ran, each line with how many tests ran it, the executable lines none runs marked. Select a line or a range for its tests and their latest outcome; on a line no test runs, the nearest test to copy.</p><figure><img src="'+c+'" alt="A file&#39;s coverage page"><figcaption>Which tests run each line.</figcaption></figure><h2 id="where-it-is-used" tabindex="-1">Where it is used <a class="header-anchor" href="#where-it-is-used" aria-label="Permalink to &quot;Where it is used&quot;">​</a></h2><ul><li><strong><a href="./test-selection.html#impact-from-diff">Impact-from-diff</a></strong> maps a changed file to the tests that executed it; a changed file no test reached still widens the run to the whole suite, since code reach misses top-level code, server code without <a href="./server-coverage.html">server coverage</a> and type-only modules.</li><li><strong><a href="./uncovered-changes.html">Uncovered changes</a></strong> counts a changed file as reached when a test executed it.</li><li><strong><a href="./preflight.html">Locator preflight</a></strong> calls a break <em>likely</em> only when one of its tests reaches the changed file.</li><li><strong><a href="./editor-coverage.html">Coverage in the editor</a></strong> marks the lines tests ran and the ones none runs, in VS Code and the JetBrains IDEs.</li><li><strong><a href="/guide/concepts.html#suspect-lines">Suspect lines</a></strong>: the changed lines a failure&#39;s tests executed, on the failure pages&#39; <a href="./failure-clusters.html#the-cluster-page">What changed</a>, in the <a href="./ai-diagnosis.html#scm-grounded-context">AI diagnosis</a> and the <a href="./fix-plans.html">fix plan</a>.</li></ul><p>The <a href="https://piwitests.dev/demo/docs" target="_blank" rel="noreferrer">API</a> (<code>/docs</code> on your instance) serves the tests reaching a file and a branch&#39;s map.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>Chromium only</strong> in the browser: other browsers have no JavaScript coverage and record no browser files. Server coverage works with every browser.</li><li><strong>Browser files are reached, not covered:</strong> a reached file may hide an untested branch.</li><li>A build with neither per-module URLs nor source maps yields nothing, and so does code rendered on the server only, React server components included.</li><li>A module whose top-level code calls its own functions, a table built on import, counts for every test that loads it.</li><li>A function a minifier inlines into another counts for the file it was inlined into.</li><li>Chromium drops the coverage of a document the page leaves, so each document is read as it goes: the capture adds a <code>beforeunload</code> listener in an isolated world, out of the page&#39;s reach, and the debugger stops on it for that read. A document left without <code>beforeunload</code> (a crash) keeps only what an earlier read saw.</li><li>On a page open before the test, what ran there before counts only if it runs again, and what a page runs on its own meanwhile (a timer, a poll) counts too.</li><li>Reach is per branch: a branch&#39;s own runs replace its tests&#39; reach, and the default branch&#39;s stands in for the rest.</li></ul><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2>',34)),n(a),e[1]||(e[1]=t('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./server-coverage.html">Server coverage</a>: the code each test ran in an ASP.NET Core backend</li><li><a href="/reference/coverage-cost.html">Coverage cost</a>: what each mode costs</li><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: what else the fixtures record</li><li><a href="./test-selection.html">Test selection</a>: impact-from-diff</li><li><a href="/guide/privacy.html">Privacy &amp; data flow</a>: what the reporter sends</li></ul>',2))])}const b=s(d,[["render",l]]);export{v as __pageData,b as default};
